mapper.select:
SELECT
    ,
    binding.binding_id
FROM employee_source_binding binding
JOIN employee employee
  ON employee.employee_id = binding.employee_id

WHERE employee.company_id = #{companyId}
  AND binding.deli_attendance_source_id = #{sourceId}
  AND binding.binding_status = 'CONFIRMED'
  AND binding.confirmation_ref IS NOT NULL
  AND binding.effective_from <= #{sourceLocalTime}
  AND (
        binding.effective_to IS NULL
        OR binding.effective_to > #{sourceLocalTime}
  )
  AND (
        (
            #{bindingKind} = 'DELI_EXT_ID'
            AND binding.deli_ext_id = #{externalPersonRef}
        )
        OR (
            #{bindingKind} = 'DELI_USER_ID'
            AND binding.deli_user_id = #{externalPersonRef}
        )
  )
ORDER BY employee.employee_id, employment.employment_period_id,
         employment.assignment_id, binding.binding_id
LIMIT 2
